   "enhance": null,
   "inhibit": null,
   "drugs": [
    {
     "en": "Strong CYP3A4 and P-glycoprotein induction lowers levels of combined oral contraceptives, anticoagulants, transplant immunosuppressants and some HIV medicines; efficacy can be lost.",
     "ar": "يؤدي تحريض إنزيم CYP3A4 والبروتين P-glycoprotein بقوة إلى خفض مستويات حبوب منع الحمل المركبة ومضادات التخثر ومثبطات المناعة المستخدمة في الزراعة وبعض أدوية فيروس نقص المناعة؛ وقد تُفقد الفعالية.",
     "sev": "high",
     "url": "https://www.nccih.nih.gov/health/st-johns-wort"
    },
    {
     "en": "Serotonergic antidepressants (SSRIs, SNRIs, triptans) can precipitate serotonin syndrome.",
     "ar": "قد تسبب مضادات الاكتئاب السيروتونينية (SSRIs وSNRIs والتريبتانات) متلازمة السيروتونين.",
     "sev": "high",
     "url": "https://www.nccih.nih.gov/health/st-johns-wort"
    }
   ],
   "deficiency": null,
   "excess": {
    "en": "MAJOR DRUG INTERACTION: Strongly induces CYP3A4 & P-gp, dangerously lowering levels of birth control pills, blood thinners, transplant drugs, HIV meds, and causing serotonin syndrome with SSRIs.",
    "ar": "تحذير دوائي شديد: تقلل فعالية أدوية كثيرة (حبوب منع الحمل، مميعات الدم، أدوية القلب والزراعة) وقد تسبب متلازمة السيروتونين مع مضادات الاكتئاب."
   },
